import { compact, number, daysAgo } from '../depot-api';
import { t, Sparkline, Stars, UserChip, CategoryLabels, SourceBadge, Cover, PriceBadge } from './bits';

/**
 * One file in a list, as a card (grid) or a row (list). The same facts in
 * both, in the same order: what it is, who made it, how current it is, and
 * how much people use and like it.
 */
export default class FileCard extends Component {
  view() {
    const {
      file,
      mode
    } = this.attrs;
    const v = file.version || {};
    const fresh = daysAgo(v.date) <= 7;
    const href = app.route('depot.file', {
      slug: file.slug
    });
    const pending = !file.approved ? m("span", {
      className: "Depot-pill Depot-pill--warn"
    }, t('card.pending')) : null;
    if (mode === 'grid') {
      return m(Link, {
        className: "DepotCard",
        href: href
      }, Cover({
        file,
        className: 'DepotCard-art',
        children: [v.version ? m("span", {
          className: "DepotCard-version"
        }, "v", v.version) : null, fresh ? m("span", {
          className: "DepotCard-fresh"
        }, t('card.updated_badge')) : null]
      }), m("div", {
        className: "DepotCard-body"
      }, m("span", {
        className: "DepotCard-labels"
      }, CategoryLabels({
        slug: file.category,
        link: false
      }), PriceBadge({
        file
      }), pending), m("h3", {
        className: "DepotCard-title"
      }, file.title), file.tagline ? m("p", {
        className: "DepotCard-tagline"
      }, file.tagline) : null, m("div", {
        className: "DepotCard-meta"
      }, UserChip({
        user: file.user
      }), v.date ? m("span", {
        className: "Depot-dim"
      }, humanTime(v.date)) : null)), m("div", {
        className: "DepotCard-foot"
      }, m("span", {
        className: "Depot-metric"
      }, m(Icon, {
        name: "fas fa-download"
      }), " ", m("b", null, compact(file.downloads))), Sparkline({
        values: file.trend,
        width: 64,
        height: 20
      }), m("span", {
        className: "Depot-metric Depot-metric--end"
      }, file.ratings ? [Stars({
        value: file.rating
      }), m("b", null, file.rating.toFixed(1))] : m("span", {
        className: "Depot-dim"
      }, t('card.no_ratings')))));
    }
    return m(Link, {
      className: "DepotRow",
      href: href
    }, Cover({
      file,
      className: 'DepotRow-thumb'
    }), m("div", {
      className: "DepotRow-main"
    }, m("h3", {
      className: "DepotRow-title"
    }, file.title, " ", v.version ? m("span", {
      className: "DepotRow-version"
    }, "v", v.version) : null, fresh ? m("span", {
      className: "Depot-pill Depot-pill--fresh"
    }, t('card.updated_badge')) : null, pending, PriceBadge({
      file
    }), SourceBadge({
      file
    })), file.tagline ? m("p", {
      className: "DepotRow-tagline"
    }, file.tagline) : null, m("div", {
      className: "DepotRow-meta"
    }, CategoryLabels({
      slug: file.category,
      link: false
    }), UserChip({
      user: file.user
    }), v.date ? m("span", {
      className: "Depot-dim"
    }, t('card.updated', {
      time: humanTime(v.date)
    }), file.compat.length ? ` · ${file.compat[0]}` : '') : null)), m("div", {
      className: "DepotRow-trend"
    }, Sparkline({
      values: file.trend,
      width: 88,
      height: 26
    }), m("span", {
      className: "Depot-dim"
    }, t('card.last_30_days'))), m("div", {
      className: "DepotRow-stats"
    }, m("span", {
      className: "DepotRow-downloads"
    }, m(Icon, {
      name: "fas fa-download"
    }), " ", number(file.downloads)), file.ratings ? m("span", {
      className: "Depot-metric"
    }, Stars({
      value: file.rating
    }), " ", m("span", {
      className: "Depot-dim"
    }, file.rating.toFixed(1))) : null));
  }
}

/**
 * A locked category, advertised: its name, how many files, and who it is for.
 * The server sends nothing else about what is inside.
 */
export function LockedCard(_ref) {
  let {
    locked,
    mode
  } = _ref;
  return m("div", {
    className: `DepotLocked DepotLocked--${mode}`,
    style: {
      '--label-color': 'var(--muted-color)'
    }
  }, m("div", {
    className: "DepotLocked-text"
  }, m(Icon, {
    name: "fas fa-lock"
  }), m("b", null, locked.name), m("span", {
    className: "Depot-dim"
  }, t('card.locked', {
    count: locked.count,
    group: locked.groups.join(', ')
  })), m("a", {
    className: "Button Button--primary Button--small",
    href: app.route('depot.category', {
      slug: locked.slug
    })
  }, t('card.see_category'))));
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/FileCard', FileCard);